```java
// Declaration only
int[] numbers;

// Initialization — all elements default to 0
numbers = new int[5];  // [0, 0, 0, 0, 0]

// Combined declaration + initialization
int[] scores = new int[3];    // [0, 0, 0]
String[] names = new String[3]; // [null, null, null]
boolean[] flags = new boolean[3]; // [false, false, false]

// Array literal — declare and fill in one line
int[] primes = {2, 3, 5, 7, 11};
String[] days = {"Mon", "Tue", "Wed"};

// Access and modify
scores[0] = 95;
System.out.println(primes.length);  // 5 — length is a field, not a method!
```

```java
import java.util.Arrays;

int[] arr = {5, 2, 8, 1, 9};

// Sort in place
Arrays.sort(arr);  // arr is now [1, 2, 5, 8, 9]

// Print as string (IMPORTANT: println(arr) just prints [I@abc123)
System.out.println(Arrays.toString(arr));  // [1, 2, 5, 8, 9]

// Fill all elements with a value
int[] filled = new int[5];
Arrays.fill(filled, 7);  // [7, 7, 7, 7, 7]

// Copy with different size
int[] bigger = Arrays.copyOf(arr, 8);  // copies arr, pads rest with 0
int[] partial = Arrays.copyOfRange(arr, 1, 4);  // elements at index 1,2,3

// Compare arrays by content
int[] a = {1, 2, 3};
int[] b = {1, 2, 3};
System.out.println(Arrays.equals(a, b));  // true
System.out.println(a == b);               // false — different objects
```

